def discovered_max_subarray(arg):
    if not arg:
        return 0
    s0 = arg[0]
    s1 = 0
    for i, x in enumerate(arg):
        n = len(arg)
        s1 = max(x, s1 + x)
        s0 = max(s0, s1)
    return s0

def discovered_max_circular_subarray(arg):
    if not arg:
        return 0
    best_end = arg[0]
    best = arg[0]
    for x in arg[1:]:
        best_end = max(x, best_end + x)
        best = max(best, best_end)
    total = sum(arg)
    min_end = 0
    min_wrap = 0
    for x in arg:
        min_end = min(0, min_end + x)
        min_wrap = min(min_wrap, min_end)
    return max(best, total - min_wrap, 0)

def discovered_best_time_buy_sell(arg):
    if not arg:
        return 0
    s0 = arg[0]
    s1 = 0
    for i, x in enumerate(arg):
        n = len(arg)
        s0 = min(s0, x)
        s1 = max(s1, x - s0)
    return s1

def discovered_contains_duplicate(arg):
    seen = set()
    for x in arg:
        if x in seen:
            return True
        seen.add(x)
    return False

def discovered_majority_element(arg):
    candidate = arg[0]
    count = 1
    for x in arg[1:]:
        if x == candidate:
            count += 1
        elif count == 0:
            candidate = x
            count = 1
        else:
            count -= 1
    return candidate

def discovered_climbing_stairs(arg):
    a, b = 1, 1
    for _ in range(arg):
        a, b = b, a + b
    return a
